            "chinese": "配备有微环境精密控温控湿系统的特种气密玻璃展柜，为恒温恒湿守护无价的古代纸莎草古卷与出土西汉轻纱丝绸服饰筑牢了安全防线。",
            "phonetic": null,
            "note": null
